import java.util.regex.Pattern;
public class T {
  static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
  static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
  static final String DEFAULT_COUNTRY_CODE = "61";
  public static void main(String[] a){
    String telephone="0400000004";
    String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
    String candidate;
    if (cleaned.startsWith("+")) candidate=cleaned;
    else { String national = cleaned.startsWith("0")? cleaned.substring(1):cleaned; candidate="+"+DEFAULT_COUNTRY_CODE+national; }
    System.out.println("candidate="+candidate+" match="+E164_PATTERN.matcher(candidate).matches());
  }
}
